<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipTrustedClientVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;

final class UserGroupMembershipTrustedClientVOUnitTest extends TestCase
{
  public function test_asignation_keep_value(): void
  {
    $value = new TrustedClientRef('one');
    $ref = UserGroupMembershipTrustedClientVO::from( $value );
    $this->assertEquals(new TrustedClientRef('one'), $ref->value());
    $other = UserGroupMembershipTrustedClientVO::tryFrom($ref, new ConstraintFailList() );
    $this->assertSame($other, $ref);
    $more = UserGroupMembershipTrustedClientVO::from($ref);
    $this->assertSame($more, $ref);
  }
  public function test_asignation_invalid_type(): void
  {
    $errors = new ConstraintFailList();
    $other = UserGroupMembershipTrustedClientVO::tryFrom('1', $errors);
    $this->assertNull($other);
    $this->assertTrue( $errors->hasErrors() );
  }
  public function test_optimist_asignation_invalid_type(): void
  {
    $this->expectException(ConstraintException::class);
    $method = new ReflectionMethod(UserGroupMembershipTrustedClientVO::class, 'fromUnsafe');
    $method->invoke(null, [11, "bad"]);
  }
  public function test_equals(): void

  {
     $one = UserGroupMembershipTrustedClientVO::from(new TrustedClientRef('one'));     $same = UserGroupMembershipTrustedClientVO::from(new TrustedClientRef('one'));     $other = UserGroupMembershipTrustedClientVO::from(new TrustedClientRef('other'));
     $withEmpty = $one->equals(null);
     $withSame = $one->equals($same);
     $withOther = $one->equals($other);

     $this->assertFalse( $withEmpty );
     $this->assertTrue( $withSame );
     $this->assertFalse( $withOther );
  }
  public function test_empty(): void
  {
    $ref = UserGroupMembershipTrustedClientVO::empty();
    $this->assertNull($ref->value());
  }
  public function test_try_from_empty(): void
  {
    $ref = UserGroupMembershipTrustedClientVO::tryFrom(null, new ConstraintFailList() );
    $this->assertNull($ref->value());
  }
}
